import math
import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

class ProjHead(nn.Module):
    def __init__(self, in_dim, out_dim):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, in_dim),
            nn.LayerNorm(in_dim),
            nn.GELU(),
            nn.Linear(in_dim, out_dim)
        )
    def forward(self, x):
        return F.normalize(self.net(x), dim=-1)

class CustomScoring(nn.Module):
    def __init__(self, mol_dim=512, pocket_dim=512, protein_dim=480, embed_dim=128):
        super().__init__()
        self.mol_project = ProjHead(mol_dim, embed_dim)
        self.pocket_project = ProjHead(pocket_dim, embed_dim)
        self.protein_project = ProjHead(protein_dim, embed_dim)
        self.logit_scale = nn.Parameter(torch.ones([1]) * np.log(13))
        self.margin = 0.1

    def project_mol(self, mol_feat):
        return self.mol_project(mol_feat)

    def project_pocket(self, poc_feat):
        return self.pocket_project(poc_feat)

    def project_protein(self, prot_feat):
        return self.protein_project(prot_feat)

    def _compute_pathway(self, sim_matrix, batch_list, act_list, mask, logit_scale):
        minus_inf = torch.finfo(sim_matrix.dtype).min
        B, N_mol = sim_matrix.shape

        pos_mask = torch.zeros_like(sim_matrix, dtype=torch.bool)
        for i, (s, e) in enumerate(batch_list):
            pos_mask[i, s:e] = True

        sim_margin = torch.where(pos_mask, sim_matrix - self.margin, sim_matrix)
        logits = sim_margin * logit_scale
        sim_masked = logits.masked_fill(mask, minus_inf)

        idx2poc = []
        for i, (s, e) in enumerate(batch_list):
            idx2poc += [i] * (e - s)
        targets = torch.tensor(idx2poc, dtype=torch.long, device=logits.device)
        lprobs_m2p = F.log_softmax(sim_masked.T, dim=-1)

        loss_m2p_list = []
        for i, (s, e) in enumerate(batch_list):
            L_i = e - s
            if L_i == 0: continue
            rows = list(range(s, e))
            loss_tmp = F.nll_loss(lprobs_m2p[rows], targets[rows], reduction="none")
            loss_m2p_list.append(loss_tmp.sum() / math.sqrt(L_i))
        loss_m2p = torch.stack(loss_m2p_list).sum() if loss_m2p_list else torch.tensor(0.0, device=logits.device)

        loss_p2m_list = []
        for i in range(B):
            s, e = batch_list[i]
            L_i = e - s
            if L_i == 0: continue
            acts = act_list[i]
            for k in range(s, e):
                if L_i > 1 and acts[k - s] < 5:
                    continue
                row_mask = torch.zeros_like(sim_masked[i])
                row_mask[s:e] = minus_inf
                row_mask[k] = 0
                lprobs = F.log_softmax(row_mask + sim_masked[i], dim=-1)
                loss_p2m_list.append(-lprobs[k] / math.sqrt(L_i))
        loss_p2m = torch.stack(loss_p2m_list).sum() if loss_p2m_list else torch.tensor(0.0, device=logits.device)

        loss_rank_list = []
        for i in range(B):
            s, e = batch_list[i]
            L_i = e - s
            if L_i <= 2: continue
            acts = act_list[i]
            out_i = sim_masked[i, s:e]
            for k_rel in range(L_i - 1):
                m_rank = torch.zeros_like(out_i)
                for idx in range(L_i):
                    if idx == k_rel: continue
                    if acts[k_rel] - math.log10(3) <= acts[idx]:
                        m_rank[idx] = minus_inf
                lprobs_rank = F.log_softmax(m_rank + out_i, dim=-1)
                loss_rank_list.append(-lprobs_rank[k_rel] / (math.log(k_rel + 2) * math.sqrt(L_i)))
        loss_rank = torch.stack(loss_rank_list).sum() if loss_rank_list else torch.tensor(0.0, device=logits.device)

        return loss_m2p + loss_p2m + loss_rank, sim_masked

    def compute_loss(self, mol_emb, poc_emb, prot_emb,
                     batch_list, act_list,
                     uniprot_poc=None, uniprot_mol=None,
                     pocket_lig_smiles=None, lig_smiles=None):
        logit_scale = torch.clamp(self.logit_scale.exp(), max=100.0)
        B = poc_emb.size(0)

        sim_poc = poc_emb @ mol_emb.T
        sim_prot = prot_emb @ mol_emb.T
        sim_joint = (sim_poc + sim_prot) / 2.0

        mask = torch.zeros_like(sim_poc, dtype=torch.bool)
        if uniprot_poc is not None and uniprot_mol is not None:
            for i in range(B):
                for j in range(mask.size(1)):
                    if uniprot_poc[i] == uniprot_mol[j]:
                        mask[i, j] = True
        if pocket_lig_smiles is not None:
            for i in range(B):
                bad = pocket_lig_smiles[i]
                for j in range(mask.size(1)):
                    if lig_smiles[j] in bad:
                        mask[i, j] = True

        loss_poc, sim_masked = self._compute_pathway(sim_poc, batch_list, act_list, mask, logit_scale)
        loss_prot, _ = self._compute_pathway(sim_prot, batch_list, act_list, mask, logit_scale)
        loss_joint, _ = self._compute_pathway(sim_joint, batch_list, act_list, mask, logit_scale)

        loss = loss_poc + loss_prot + loss_joint

        return loss, {
            "loss": loss.item(),
            "loss_poc": loss_poc.item(),
            "loss_prot": loss_prot.item(),
            "loss_joint": loss_joint.item(),
            "sim_masked": sim_masked,
        }

    def score(self, mol_reps, pocket_reps, prot_reps=None):
        poc_scores = (pocket_reps @ mol_reps.T).max(axis=0)
        if prot_reps is not None:
            prot_scores = (prot_reps @ mol_reps.T).max(axis=0)
            return (poc_scores + prot_scores) / 2.0
        return poc_scores
